/**
 * Scenario "pet-sold" - generated by postman-mock app-mock.mjs from ./default.js
 */
const http = require('http');
const PORT = process.env.PORT || 4501;

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || '', 'http://localhost');
  const pathname = url.pathname;

  // ─── scenario "pet-sold" overrides ───
  // @endpoint GET /v1/pets/:petId  (scenario override)
  if (req.method === "GET" && /^\/v1\/pets\/[^\/]+$/.test(pathname)) {
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end("{\"id\":7,\"name\":\"Luna\",\"status\":\"sold\"}");
  }

  // @endpoint GET /v1/pets  (scenario override)
  if (req.method === "GET" && /^\/v1\/pets$/.test(pathname) && url.searchParams.get("status") === "sold") {
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end("[]");
  }

  // @endpoint POST /v1/auth/login  (scenario override)
  if (req.method === "POST" && /^\/v1\/auth\/login$/.test(pathname)) {
    await new Promise(r => setTimeout(r, 800));
    res.writeHead(401, {"Content-Type":"application/json"});
    return res.end("{\"code\":\"ACCOUNT_LOCKED\",\"message\":\"Account is locked\"}");
  }


  // @endpoint GET /v1/pets
  if (req.method === 'GET' && pathname === '/v1/pets') {
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify([{"id":1,"name":"Milo","status":"available"},{"id":2,"name":"Luna","status":"sold"}]));
  }

  // @endpoint POST /v1/pets
  if (req.method === 'POST' && pathname === '/v1/pets') {
    const requestedStatusCode = req.headers['x-mock-response-code'];

    // "Validation error" — when x-mock-response-code: 400
    if (requestedStatusCode === '400') {
      res.writeHead(400, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"code":"VALIDATION_ERROR","message":"name is required"}));
    }

    // "Created" — default
    res.writeHead(201, {"Content-Type":"application/json"});
    return res.end(JSON.stringify({"id":3,"name":"Milo","status":"available"}));
  }

  // @endpoint GET /v1/pets/:petId
  if (req.method === 'GET' && /^\/v1\/pets\/([^/]+)$/.test(pathname)) {
    const requestedStatusCode = req.headers['x-mock-response-code'];

    // "Not found" — when x-mock-response-code: 404
    if (requestedStatusCode === '404') {
      res.writeHead(404, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"code":"PET_NOT_FOUND","message":"Pet not found"}));
    }

    // "The pet" — default
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify({"id":1,"name":"Milo","status":"available"}));
  }

  // @endpoint DELETE /v1/pets/:petId
  if (req.method === 'DELETE' && /^\/v1\/pets\/([^/]+)$/.test(pathname)) {
    res.writeHead(204, {"Content-Type":"text/plain"});
    return res.end("");
  }

  // @endpoint POST /v1/auth/login
  if (req.method === 'POST' && pathname === '/v1/auth/login') {
    const requestedStatusCode = req.headers['x-mock-response-code'];

    // "Wrong credentials" — when x-mock-response-code: 401
    if (requestedStatusCode === '401') {
      res.writeHead(401, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"code":"INVALID_CREDENTIALS","message":"Email or password is incorrect"}));
    }

    // "Logged in" — default
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify({"token":"eyJhbGciOi.example","expiresIn":3600}));
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Endpoint not defined' }));
});

server.listen(PORT);
